"""TypeScript core pack, part 2: Narrowing, Does tsc Accept It? and Generics.

Answers are worked out by hand in Python; tests/brain_check.py tscore holds them to the real `tsc --strict` and node.
"""

from __future__ import annotations

from ._model import Maker
from ._tscore_basics import K, bits
from ._ts_model import TS, js_show

# -- 2. Narrowing ---------------------------------------------------------

NARROW: list[Maker] = [
    TS('function f(x: string | number) { return typeof x === "string" ? x.length : x * 2; }\nconsole.log(f("$w"), f($a));',
       K(lambda w, a, **_: f"{len(w)} {a * 2}"), "A string takes the length branch, a number the doubling branch."),
    TS('function f(x: string | number) {\n  if (typeof x === "number") return x + 1;\n  return x + "!";\n}\nconsole.log(f($a), f("$w"));',
       K(lambda a, w, **_: f"{a + 1} {w}!"), "typeof splits the union, so each kind is handled by its own return."),
    TS('function f(x: string[] | string) { return Array.isArray(x) ? x.join("-") : x; }\nconsole.log(f(["$w", "$z"]), f("$w"));',
       K(lambda w, z, **_: f"{w}-{z} {w}"), "Array.isArray tells the array from the string."),
    TS("type S = { kind: \"sq\"; s: number } | { kind: \"rect\"; w: number; h: number };\nfunction area(s: S) { return s.kind === \"sq\" ? s.s * s.s : s.w * s.h; }\nconsole.log(area({ kind: \"rect\", w: $a, h: $b }));",
       K(lambda a, b, **_: a * b), "The kind tag selects the rect branch, so the area is width times height."),
    TS("type S = { kind: \"sq\"; s: number } | { kind: \"rect\"; w: number; h: number };\nfunction area(s: S) { return s.kind === \"sq\" ? s.s * s.s : s.w * s.h; }\nconsole.log(area({ kind: \"sq\", s: $a }));",
       K(lambda a, **_: a * a), "The kind tag selects the square branch."),
    TS('type D = { name: string } | { id: number };\nfunction f(x: D) { return "id" in x ? x.id + 1 : x.name; }\nconsole.log(f({ id: $a }), f({ name: "$w" }));',
       K(lambda a, w, **_: f"{a + 1} {w}"), "The in operator checks whether the property exists."),
    TS('function f(e: Error | string) { return e instanceof Error ? e.message : e; }\nconsole.log(f(new Error("$w")), f("$z"));',
       K(lambda w, z, **_: f"{w} {z}"), "instanceof Error picks out the Error object."),
    TS('function f(s?: string) { if (s) return s.length; return -1; }\nconsole.log(f(), f(""), f("$w"));',
       K(lambda w, **_: f"-1 -1 {len(w)}"), "The empty string is falsy, so it takes the same branch as undefined."),
    TS('function f(s: string | null) { return s === null ? "none" : s.toUpperCase(); }\nconsole.log(f(null), f("$w"));',
       K(lambda w, **_: f"none {w.upper()}"), "After the null check the string methods are allowed."),
    TS('function f(s: string | null) { return s?.length ?? 0; }\nconsole.log(f(null), f("$w"));',
       K(lambda w, **_: f"0 {len(w)}"), "Optional chaining gives undefined for null, and the fallback makes it 0."),
    TS("function f(x: number | null | undefined) { if (x == null) return \"nothing\"; return x * $a; }\nconsole.log(f(null), f(undefined), f(0));",
       "nothing nothing 0", "Loose equality with null catches both nothings, and 0 is a real number."),
    TS('function isStr(x: unknown): x is string { return typeof x === "string"; }\nconst xs: unknown[] = [$a, "$w", true];\nconsole.log(xs.filter(isStr));',
       K(lambda w, **_: [w]), "The type guard keeps only the strings."),
    TS('function f(x: unknown) { return typeof x === "number" ? x + $a : "no"; }\nconsole.log(f($b), f("$w"));',
       K(lambda a, b, **_: f"{a + b} no"), "unknown must be narrowed with typeof before it can be added."),
    TS('function f(x: string | number | boolean) {\n  if (typeof x === "string") return "s";\n  if (typeof x === "number") return "n";\n  return "b";\n}\nconsole.log(f(true), f($a), f("$w"));',
       "b n s", "Each typeof test removes one member of the union."),
    TS('function f(x: string | string[]) { return typeof x === "object" ? x.length : -1; }\nconsole.log(f(["$w", "$z"]), f("$w"));',
       "2 -1", "typeof an array is object, so the array takes the first branch."),
    TS('const xs: (string | number)[] = [$a, "$w", $b];\nlet sum = 0;\nlet text = "";\nfor (const v of xs) {\n  if (typeof v === "number") sum += v; else text += v;\n}\nconsole.log(sum, text);',
       K(lambda a, b, w, **_: f"{a + b} {w}"), "Numbers are added to the sum and strings are appended to the text."),
    TS('const xs: (string | number)[] = [$a, "$w", $b];\nconsole.log(xs.filter((v): v is number => typeof v === "number"));',
       K(lambda a, b, **_: [a, b]), "The type predicate keeps only the numbers."),
    TS("function f(x: (() => number) | number) { return typeof x === \"function\" ? x() : x; }\nconsole.log(f(() => $a), f($b));",
       K(lambda a, b, **_: f"{a} {b}"), "A function is called, a number is returned as it is."),
    TS('type R = { ok: true; value: number } | { ok: false; error: string };\nfunction f(r: R) { return r.ok ? r.value * 2 : r.error; }\nconsole.log(f({ ok: true, value: $a }), f({ ok: false, error: "$w" }));',
       K(lambda a, w, **_: f"{a * 2} {w}"), "The ok flag decides which fields exist."),
    TS('type A = { swim(): string };\ntype B = { fly(): string };\nfunction f(x: A | B) { return "swim" in x ? x.swim() : x.fly(); }\nconsole.log(f({ fly: () => "$w" }));',
       K(lambda w, **_: w), "The object has no swim method, so the fly branch runs."),
    TS('function f(a: string | number, b: string | boolean) { return a === b ? "same:" + a.length : "diff"; }\nconsole.log(f("$w", "$w"), f($a, "$w"));',
       K(lambda w, **_: f"same:{len(w)} diff"), "Equality can only hold when both are the shared type, so a is a string there."),
    TS('function f(n?: number) { return n ? n : -1; }\nconsole.log(f(0), f($a), f());', K(lambda a, **_: f"-1 {a} -1"),
       "0 is falsy, so it falls into the same branch as undefined."),
    TS('function f(n?: number) { return n !== undefined ? n : -1; }\nconsole.log(f(0), f($a), f());', K(lambda a, **_: f"0 {a} -1"),
       "Comparing with undefined keeps the real 0."),
    TS("function f(x: string | null | undefined) { return x ?? \"none\"; }\nconsole.log(f(null), f(undefined), f(\"$w\"));",
       K(lambda w, **_: f"none none {w}"), "The double question mark covers both nothings."),
    TS("function f(x: number | number[]) { return Array.isArray(x) ? x.reduce((s, v) => s + v, 0) : x; }\nconsole.log(f([$a, $b, $c]), f($d));",
       K(lambda a, b, c, d, **_: f"{a + b + c} {d}"), "An array is summed, a plain number is returned."),
    TS('class Dog { bark() { return "woof"; } }\nclass Cat { meow() { return "meow"; } }\nfunction f(p: Dog | Cat) { return p instanceof Dog ? p.bark() : p.meow(); }\nconsole.log(f(new Cat()), f(new Dog()));',
       "meow woof", "instanceof picks the matching class."),
    TS('function f(x: string | number) { return typeof x === "string" && x.length > $a; }\nconsole.log(f("$w"), f($b));',
       K(lambda w, a, **_: bits(len(w) > a, False)), "The length test runs only for strings, a number gives false."),
    TS('function f(x: string | number) {\n  if (typeof x === "number") return "n";\n  return x.toUpperCase();\n}\nconsole.log(f("$w"), f($a));',
       K(lambda w, **_: f"{w.upper()} n"), "The early return removes number from the union."),
    TS('type D = "up" | "down";\nfunction f(d: D) { return d === "up" ? $a : -$a; }\nconsole.log(f("down"), f("up"));',
       K(lambda a, **_: f"-{a} {a}"), "The literal union has only two values to test."),
    TS("function t(x: string | null | number[]) { return typeof x; }\nconsole.log(t(null), t(\"$w\"), t([$a]));", "object string object",
       "typeof null and typeof an array are both object."),
    TS("const shapes: ({ k: \"c\"; r: number } | { k: \"s\"; n: number })[] = [{ k: \"c\", r: $a }, { k: \"s\", n: $b }];\nconsole.log(shapes.map(s => (s.k === \"c\" ? s.r : s.n * 2)));",
       K(lambda a, b, **_: [a, b * 2]), "Each element is narrowed by its own tag."),
    TS('let x: string | number = "$w";\nx = $a;\nconsole.log(typeof x, x + 1);', K(lambda a, **_: f"number {a + 1}"),
       "Assigning a number narrows x to number from that point on."),
    TS('function f(x: string | undefined) {\n  if (!x) return "empty";\n  return x.length;\n}\nconsole.log(f(undefined), f(""), f("$w"));',
       K(lambda w, **_: f"empty empty {len(w)}"), "Both undefined and the empty string are falsy."),
    TS('function f(x: number | string) {\n  switch (typeof x) {\n    case "number": return x * $a;\n    default: return x.length;\n  }\n}\nconsole.log(f($b), f("$w"));',
       K(lambda a, b, w, **_: f"{a * b} {len(w)}"), "A switch on typeof narrows in each case."),
    TS('type E = { t: "+"; n: number } | { t: "0" };\nlet s = $a;\nconst es: E[] = [{ t: "+", n: $b }, { t: "0" }, { t: "+", n: $c }];\nfor (const e of es) s = e.t === "+" ? s + e.n : 0;\nconsole.log(s);',
       K(lambda c, **_: c), "The reset throws away the earlier total, then the last add counts."),
]

# -- 3. Does tsc Accept It? ----------------------------------------------

E, F = "error", "fine"


def _c(code: str, ans: str, why: str) -> Maker:
    return TS(code, ans, why)


COMPILE: list[Maker] = [
    _c('let n: number = "$w";', E, "A string cannot be assigned to a number."),
    _c('let n: number = $a;\nn = "$w";', E, "n was declared as a number, so a string is refused."),
    _c("interface P { x: number; y: number }\nconst p: P = { x: $a };", E, "The property y is missing."),
    _c("interface P { x: number }\nconst p: P = { x: $a, y: $b };", E, "An object literal may not have extra properties."),
    _c("function f(s?: string) { return s.length; }", E, "s may be undefined, so reading length is refused."),
    _c("interface P { readonly x: number }\nconst p: P = { x: $a };\np.x = $b;", E, "A readonly property cannot be assigned."),
    _c("function f(a, b: number) { return b; }", E, "The parameter a has no type, so it is an implicit any."),
    _c("function f(n: number): string { return n; }", E, "The function promises a string but returns a number."),
    _c('type S = "a" | "b" | "c";\nfunction f(s: S): number {\n  switch (s) {\n    case "a": return 1;\n    case "b": return 2;\n    default: { const x: never = s; return x; }\n  }\n}',
       E, "The value c is not handled, so s is not never in the default branch."),
    _c('type S = "a" | "b";\nfunction f(s: S): number {\n  switch (s) {\n    case "a": return $a;\n    case "b": return $b;\n    default: { const x: never = s; return x; }\n  }\n}\nconsole.log(f("b"));',
       F, "Every case is handled, so s is never in the default branch."),
    _c("const xs = [$a, $b] as const;\nxs.push($c);", E, "An as const array is readonly, so push does not exist."),
    _c("const xs: number[] = [$a, $b];\nxs.push($c);\nconsole.log(xs.length);", F, "A normal array can be pushed to."),
    _c("function f(x: unknown) { return x.toString(); }", E, "An unknown value must be narrowed before use."),
    _c('function f(x: unknown) { return typeof x === "string" ? x.toUpperCase() : ""; }\nconsole.log(f("$w"));', F, "typeof narrows unknown to string."),
    _c("function f(x: string | number) { return x.toFixed(2); }", E, "toFixed does not exist on a string."),
    _c("let x: string | number = $a;\nconsole.log(x.toFixed(2));", F, "The assignment narrowed x to number."),
    _c('function f(x: string | number) { return typeof x === "number" ? x.toFixed(1) : x.trim(); }\nconsole.log(f($a));', F, "Both branches use a method the narrowed type has."),
    _c("const o = { a: $a };\no.b = $b;", E, "The object has no property b."),
    _c('const xs: number[] = [$a, "$w"];', E, "A string cannot be an element of a number array."),
    _c('const t: [number, string] = [$a, "$w", $b];', E, "The tuple allows exactly two elements."),
    _c('const t: [number, string] = [$a, "$w"];\nconsole.log(t[2]);', E, "A two-element tuple has no index 2."),
    _c('const t: [number, string] = [$a, "$w"];\nconsole.log(t[1].length);', F, "Index 1 is known to be a string."),
    _c("function f(a: number, b: number) { return a + b; }\nf($a);", E, "The call has too few arguments."),
    _c("function f(a: number, b: number) { return a + b; }\nf($a, $b, $c);", E, "The call has too many arguments."),
    _c("function f(a: number, b = $b) { return a + b; }\nconsole.log(f($a));", F, "A parameter with a default may be left out."),
    _c('let s = "$w";\ns = null;', E, "Under strict, null is not a string."),
    _c("const n: number = null;", E, "Under strict, null is not a number."),
    _c('type A = { kind: "a" };\nconst a: A = { kind: "b" };', E, "The literal b is not the allowed a."),
    _c('class C { constructor(public x: number) {} }\nnew C("$w");', E, "The constructor wants a number."),
    _c("class C { private x = $a; }\nconsole.log(new C().x);", E, "A private member cannot be read outside the class."),
    _c("class C { x: number; }", E, "Strict mode wants x initialised."),
    _c("class C { x = $a; }\nconsole.log(new C().x);", F, "The field has an initialiser."),
    _c("abstract class A { abstract f(): number; }\nnew A();", E, "An abstract class cannot be instantiated."),
    _c("interface Shape { area(): number }\nclass Sq implements Shape {}", E, "Sq does not provide area."),
    _c("interface Shape { area(): number }\nclass Sq implements Shape { area() { return $a; } }\nconsole.log(new Sq().area());", F, "Sq provides area."),
    _c("const o: any = null;\nconsole.log(o.x);", E, "tsc is happy with any, but reading x of null throws at run time."),
    _c("const xs: number[] = [];\nconsole.log(xs[0].toFixed(1));", E, "tsc trusts the index, but xs[0] is undefined at run time and the call throws."),
    _c("const m = new Map<string, number>();\nconsole.log(m.get(\"$w\")!.toFixed(1));", E, "The exclamation mark hides the problem, but the value is undefined and the call throws."),
    _c('function f(x: number) { return x; }\nf("$a");', E, "A string is not a number."),
    _c("function f(s?: string) { return s?.length; }\nconsole.log(f());", F, "Optional chaining makes the access safe."),
    _c('function isStr(x: unknown): x is string { return typeof x === "string"; }\nfunction f(x: unknown) { return isStr(x) ? x.length : 0; }\nconsole.log(f("$w"));', F, "The type guard narrows x to string."),
    _c("const o: { a: number; b?: number } = { a: $a };\nconsole.log(o.b);", F, "b is optional, so leaving it out is fine."),
    _c("interface P { x: number }\nconst p = { x: $a, y: $b };\nconst q: P = p;\nconsole.log(q.x);", F, "Extra properties are only refused in a fresh object literal."),
    _c('const n: number = Number("$w");', F, "Number returns a number, even if it is NaN."),
    _c('const n: number = "5" * 2;', E, "Arithmetic on a string is refused."),
    _c('const n = Number("5") * $a;\nconsole.log(n);', F, "Number first, then arithmetic."),
    _c("enum Color { Red, Green }\nconst c: Color = Color.Green;\nconsole.log(c);", F, "Color.Green is a Color."),
    _c('enum Color { Red, Green }\nconst c: Color = "Red";', E, "A string is not a member of a numeric enum."),
    _c("class C { constructor(readonly x: number) {} }\nconst c = new C($a);\nc.x = $b;", E, "A readonly parameter property cannot be assigned."),
    _c("class C { constructor(readonly x: number) {} }\nconst c = new C($a);\nconsole.log(c.x);", F, "Reading a readonly property is fine."),
    _c('function f<T>(x: T): T { return x; }\nconst n: number = f("$w");', E, "T is inferred as string, which is not a number."),
    _c("function f<T>(x: T): T { return x; }\nconst n: number = f($a);\nconsole.log(n);", F, "T is inferred as number."),
    _c("function first<T>(xs: T[]): T { return xs[0]; }\nconst s: string = first([$a, $b]);", E, "first of a number array is a number."),
    _c("const xs: readonly number[] = [$a];\nxs.push($b);", E, "A readonly array has no push."),
    _c('type T = { a: number } | { b: string };\nfunction f(t: T) { return t.a; }', E, "Property a does not exist on every member of the union."),
    _c('type T = { a: number } | { b: string };\nfunction f(t: T) { return "a" in t ? t.a : 0; }\nconsole.log(f({ a: $a }));', F, "The in check narrows to the member with a."),
    _c('const f: (n: number) => number = (n) => n + "$w";', E, "The function returns a string, not a number."),
    _c("const f: (n: number) => number = (n) => n + $a;\nconsole.log(f($b));", F, "The function returns a number."),
    _c("const x = $a as string;", E, "A direct assertion between unrelated types is refused."),
    _c('const x = "$w" as string;\nconsole.log(x);', F, "The assertion is to the type it already has."),
    _c("const [p, q, r] = [$a, $b];\nconsole.log(r);", E, "The array literal is a two-element tuple here, so r has no index."),
    _c("const xs = [$a, $b];\nconst [p, q, r] = xs;\nconsole.log(r);", F, "A number array has any index, so r is typed as number."),
    _c("console.log($w);", E, "The word is not defined as a variable."),
    _c("const n = $a;\nn = $b;", E, "A const cannot be reassigned."),
    _c("let n = $a;\nn = $b;\nconsole.log(n);", F, "A let can be reassigned."),
    _c("function f(n: number): number {\n  if (n > $a) { return 1; }\n}", E, "Some paths end without returning a number."),
    _c("function f(n: number): number {\n  if (n > $a) { return 1; }\n  return 0;\n}\nconsole.log(f($b));", F, "Every path returns a number."),
    _c("const o = { a: $a } as const;\no.a = $b;", E, "as const makes the properties readonly."),
    _c("interface A { n: number }\ninterface B extends A { s: string }\nconst b: B = { n: $a };", E, "B also needs the property s."),
    _c('interface A { n: number }\ninterface B extends A { s: string }\nconst b: B = { n: $a, s: "$w" };\nconsole.log(b.s);', F, "B has both properties."),
    _c("const o = { a: $a };\nfor (const k of Object.keys(o)) console.log(o[k]);", E, "A plain string cannot index an object of known shape."),
    _c("const o = { a: $a };\nfor (const k of Object.keys(o)) console.log(o[k as keyof typeof o]);", F, "The assertion makes k a valid key."),
    _c('function f() { throw new Error("$w"); }\nf();', E, "tsc accepts it, but the call throws."),
    _c('function f(): never { throw new Error("$w"); }\nconsole.log($a);', F, "f is never called, so nothing throws."),
    _c("const o = JSON.parse('{\"a\":$a}');\nconsole.log(o.a);", F, "JSON.parse returns any and the text is valid."),
    _c("const o = JSON.parse(\"{$w}\");\nconsole.log(o);", E, "tsc accepts it, but the text is not valid JSON and parse throws."),
    _c("const s: string = [$a, $b].join();", F, "join returns a string."),
    _c("const s: number = [$a, $b].join();", E, "join returns a string, not a number."),
    _c("const p: Promise<number> = $a;", E, "A number is not a Promise."),
    _c("let u: string | undefined = undefined;\nu = \"$w\";\nconsole.log(u.length);", F, "After the assignment u is known to be a string."),
    _c("function f(x?: number) { return x + $a; }", E, "x may be undefined, so the addition is refused."),
    _c("function f(x?: number) { return (x ?? 0) + $a; }\nconsole.log(f());", F, "The fallback removes undefined."),
    _c('const x: "a" | "b" = "c";', E, "c is not in the union."),
    _c('let x: "a" | "b" = "a";\nx = "b";\nconsole.log(x);', F, "b is in the union."),
]

# -- 4. Generics ----------------------------------------------------------

GENERICS: list[Maker] = [
    TS('function id<T>(x: T): T { return x; }\nconsole.log(id($a), id("$w"));', K(lambda a, w, **_: f"{a} {w}"), "id returns whatever it is given."),
    TS('function first<T>(xs: T[]): T | undefined { return xs[0]; }\nconsole.log(first([$a, $b, $c]), first(["$w", "$z"]));',
       K(lambda a, w, **_: f"{a} {w}"), "first returns the element at index 0."),
    TS("function first<T>(xs: T[]): T | undefined { return xs[0]; }\nconsole.log(first([]), first([$a]));", K(lambda a, **_: f"undefined {a}"),
       "An empty array has no element 0."),
    TS('function wrap<T>(x: T): T[] { return [x]; }\nconsole.log(wrap($a), wrap("$w"));', K(lambda a, w, **_: f"[ {a} ] [ '{w}' ]"),
       "wrap puts its argument in an array of one."),
    TS('function swap<A, B>(p: [A, B]): [B, A] { return [p[1], p[0]]; }\nconsole.log(swap([$a, "$w"]));', K(lambda a, w, **_: [w, a]), "swap reverses the pair."),
    TS('function get<T, K extends keyof T>(o: T, k: K): T[K] { return o[k]; }\nconst o = { $w: $a, $z: $b };\nconsole.log(get(o, "$z"));',
       K(lambda b, **_: b), "get reads the property named by the key."),
    TS('function len<T extends { length: number }>(x: T) { return x.length; }\nconsole.log(len("$w"), len([$a, $b, $c]));',
       K(lambda w, **_: f"{len(w)} 3"), "Strings and arrays both have a length."),
    TS("class Stack<T> {\n  private xs: T[] = [];\n  push(x: T) { this.xs.push(x); }\n  pop() { return this.xs.pop(); }\n}\nconst s = new Stack<number>();\ns.push($a); s.push($b);\nconsole.log(s.pop(), s.pop(), s.pop());",
       K(lambda a, b, **_: f"{b} {a} undefined"), "A stack gives back the last pushed first, and undefined once empty."),
    TS("class Box<T> {\n  constructor(public v: T) {}\n  map<U>(f: (v: T) => U) { return new Box(f(this.v)); }\n}\nconsole.log(new Box($a).map(n => n * $b).v);",
       K(lambda a, b, **_: a * b), "map applies the function to the stored value."),
    TS('class Box<T> {\n  constructor(public v: T) {}\n  map<U>(f: (v: T) => U) { return new Box(f(this.v)); }\n}\nconsole.log(new Box("$w").map(s => s.length).map(n => n + $a).v);',
       K(lambda w, a, **_: len(w) + a), "The box holds the length, then that length plus a."),
    TS('const r: Record<string, number> = { $w: $a };\nr["$z"] = $b;\nconsole.log(Object.keys(r).length, r.$w + r.$z);',
       K(lambda a, b, **_: f"2 {a + b}"), "The record now has two keys, and the values add."),
    TS("interface P { x: number; y: number }\nconst d: P = { x: $a, y: $b };\nconst u: Partial<P> = { y: $c };\nconsole.log({ ...d, ...u });",
       K(lambda a, c, **_: {"x": a, "y": c}), "The later spread overrides y."),
    TS('const full = { id: $a, name: "$w", age: $b };\nconst p: Pick<typeof full, "id" | "name"> = full;\nconsole.log(p);',
       K(lambda a, w, b, **_: {"id": a, "name": w, "age": b}), "Pick is only a type: the object still has all three fields."),
    TS("function map<T, U>(xs: T[], f: (x: T) => U): U[] {\n  const out: U[] = [];\n  for (const x of xs) out.push(f(x));\n  return out;\n}\nconsole.log(map([$a, $b, $c], x => x * $k));",
       K(lambda a, b, c, k, **_: [a * k, b * k, c * k]), "Each element is multiplied by k."),
    TS("function last<T>(xs: T[]): T { return xs[xs.length - 1]; }\nconsole.log(last([$a, $b, $c]), last([\"$w\", \"$z\"]));",
       K(lambda c, z, **_: f"{c} {z}"), "last reads the final element."),
    TS("function pair<A, B>(a: A, b: B) { return { a, b }; }\nconsole.log(pair($a, \"$w\"));", K(lambda a, w, **_: {"a": a, "b": w}),
       "The shorthand properties take the argument names."),
    TS("function count<T>(xs: T[], v: T) { return xs.filter(x => x === v).length; }\nconsole.log(count([$a, $b, $a, $c, $a], $a));", K(lambda **_: 3),
       "The value appears three times."),
    TS("function merge<A, B>(a: A, b: B): A & B { return { ...a, ...b }; }\nconsole.log(merge({ x: $a }, { y: $b }));", K(lambda a, b, **_: {"x": a, "y": b}),
       "merge combines both objects."),
    TS("function merge<A, B>(a: A, b: B): A & B { return { ...a, ...b }; }\nconsole.log(merge({ x: $a, y: $b }, { y: $c }));", K(lambda a, c, **_: {"x": a, "y": c}),
       "The second object wins on y."),
    TS('const m = new Map<string, number>();\nm.set("$w", $a);\nm.set("$w", $b);\nconsole.log(m.size, m.get("$w"));', K(lambda b, **_: f"1 {b}"),
       "Setting the same key twice replaces the value."),
    TS("const s = new Set<number>([$a, $b, $a]);\nconsole.log(s.size, s.has($b));", "2 true", "A set drops duplicates."),
    TS("function compose<A, B, C>(f: (a: A) => B, g: (b: B) => C) { return (x: A) => g(f(x)); }\nconsole.log(compose((n: number) => n + $a, (n: number) => n * $b)($c));",
       K(lambda a, b, c, **_: (c + a) * b), "f runs first, then g."),
    TS('function sumBy<T>(xs: T[], f: (x: T) => number) { return xs.reduce((s, x) => s + f(x), 0); }\nconsole.log(sumBy(["$w", "$z"], s => s.length));',
       K(lambda w, z, **_: len(w) + len(z)), "The lengths are added up."),
    TS('interface Pair<K, V> { key: K; value: V }\nconst p: Pair<string, number> = { key: "$w", value: $a };\nconsole.log(p.key + p.value);', K(lambda w, a, **_: f"{w}{a}"),
       "A string plus a number glues them."),
    TS('const counts: Record<string, number> = {};\nfor (const ch of "$w") counts[ch] = (counts[ch] ?? 0) + 1;\nconsole.log(counts["$f"]);',
       K(lambda w, f, **_: w.count(f)), "Each letter is counted as it is met."),
    TS("function pad<T>(xs: T[], v: T, n: number): T[] {\n  while (xs.length < n) xs = [...xs, v];\n  return xs;\n}\nconsole.log(pad([$a], $b, 3));",
       K(lambda a, b, **_: [a, b, b]), "The array is padded with b until it has 3 items."),
    TS('function maxOf<T extends number | string>(xs: T[]): T {\n  return xs.reduce((m, x) => (x > m ? x : m));\n}\nconsole.log(maxOf([$a, $b, $c]), maxOf(["$w", "$z"]));',
       K(lambda a, b, c, w, z, **_: f"{max(a, b, c)} {max(w, z)}"), "Numbers compare by value, strings by dictionary order."),
    TS("const o = { a: $a, b: $b };\ntype K = keyof typeof o;\nconst k: K = \"b\";\nconsole.log(o[k]);", K(lambda b, **_: b), "keyof typeof gives the property names, and b is one."),
    TS('function setProp<T, K extends keyof T>(o: T, k: K, v: T[K]) { o[k] = v; }\nconst o = { n: $a, s: "$w" };\nsetProp(o, "n", $b);\nconsole.log(o);',
       K(lambda b, w, **_: {"n": b, "s": w}), "setProp changes only the named property."),
    TS("class Q<T> {\n  xs: T[] = [];\n  add(x: T) { this.xs.push(x); }\n  next() { return this.xs.shift(); }\n}\nconst q = new Q<number>();\nq.add($a); q.add($b);\nconsole.log(q.next(), q.xs.length);",
       K(lambda a, **_: f"{a} 1"), "A queue gives back the first added, leaving one."),
    TS('class C<T> {\n  m = new Map<T, number>();\n  add(x: T) { this.m.set(x, (this.m.get(x) ?? 0) + 1); return this; }\n}\nconst c = new C<string>().add("$w").add("x").add("$w");\nconsole.log(c.m.get("$w"));',
       "2", "The word was added twice, so its count is 2."),
    TS("console.log(Array.from({ length: $k + 1 }, (_, i) => i * $a));", K(lambda k, a, **_: [i * a for i in range(k + 1)]), "The index is multiplied by a."),
    TS("function toArr<T>(x: T | T[]): T[] { return Array.isArray(x) ? x : [x]; }\nconsole.log(toArr($a), toArr([$a, $b]));",
       K(lambda a, b, **_: f"[ {a} ] [ {a}, {b} ]"), "A single value is wrapped, an array is kept."),
    TS("const o = { a: $a, b: $b };\nconst p: Omit<typeof o, \"a\"> = o;\nconsole.log(Object.keys(p).length);", "2", "Omit only changes the type, the object still has both keys."),
    TS('const full = { id: $a, name: "$w" };\nconst p: Readonly<typeof full> = full;\nconsole.log(p.id + p.name.length);', K(lambda a, w, **_: a + len(w)),
       "Readonly only blocks writing, reading works."),
    TS("function zip<A, B>(a: A[], b: B[]): [A, B][] {\n  return a.map((x, i) => [x, b[i]] as [A, B]);\n}\nconsole.log(zip([$a, $b], [\"$w\", \"$z\"]));",
       K(lambda a, b, w, z, **_: [[a, w], [b, z]]), "zip pairs up items at the same index."),
    TS("function tap<T>(x: T, f: (x: T) => void): T { f(x); return x; }\nlet seen = 0;\nconst r = tap($a, x => { seen = x * $b; });\nconsole.log(r, seen);",
       K(lambda a, b, **_: f"{a} {a * b}"), "tap returns its value unchanged and the callback records a side effect."),
]
